                                threaten: 4,
                                result: {
                                    target(player, target) {
                                        if (ui.selected.targets.length == 0) {
                                            return -target.countCards('h');
                                        } else {
                                            return -get.effect(target, { name: 'lg_buwu' }, ui.selected.targets[0]);
                                        }
                                    },
                                },
