                                        var phase = ['phaseZhunbei', 'phaseJudge', 'phaseDraw', 'phaseUse', 'phaseDiscard', 'phaseJieshu'];
                                        for (var p of phase) {
                                            if (_status.event.getParent(p, true)) return p;
                                        }
                                        return null;
