                        lg_lunzhuanshenglizhijian: {
                            nobracket: true,
                            audio: 'ext:诸神黄昏/audio:2',
                            trigger: {
                                global: 'roundStart',
                            },
                            filter(event, player) {
                                return player.countCards('e') > 1;
                            },
                            check(event, player) {
                                var active = 0;
                                for (var i of game.players) {
                                    //QQ
                                    if (i == player) continue;
                                    if (!i.isOut()) {
                                        if (get.attitude(player, i) > 0) {
                                            if (get.distance(player, i, 'attack') <= 1) {
                                                active--;
                                                if (i.hp > 1) active += 0.5;
                                            }
                                        } else if (get.attitude(player, i) < 0) {
                                            if (get.distance(player, i, 'attack') <= 1) {
                                                active++;
                                                if (i.hp <= 1) active += 0.5;
                                            }
                                        }
                                    }
                                }
                                if (active > 0) return 1;
                                return 0;
                            },
                            content() {
                                'step 0';
                                player.chooseToDiscard(2, true, 'e');
                                ('step 1');
                                var targets = [];
                                for (var i of game.players) {
                                    //QQ
                                    if (i == player) continue;
                                    if (!i.isOut()) {
                                        if (get.distance(player, i, 'attack') <= 1) {
                                            targets.push(i);
                                        }
                                    }
                                }
                                for (var i = 0; i < targets.length; i++) {
                                    var mubiao = targets[i];
                                    player.line(mubiao, 'metal');
                                    targets[i].damage(2);
                                }
                            },
                            ai: {
                                basic: {
                                    order: 1,
                                    useful: 1,
                                    value: 5,
                                },
                                wuxie(target, card, player, viewer) {
                                    if (get.attitude(viewer, target) > 0 && target.countCards('h', 'shan')) {
                                        if (!target.countCards('h') || target.hp == 1 || Math.random() < 0.7) return 0;
                                    }
                                },
                                result: {
                                    target(player, target) {
                                        if (player.hasUnknown(2) && get.mode() != 'guozhan') return 0;
                                        var nh = target.countCards('h');
                                        if (get.mode() == 'identity') {
                                            if (target.isZhu && nh <= 2 && target.hp <= 1) return -100;
                                        }
                                        if (nh == 0) return -2;
                                        if (nh == 1) return -1.7;
                                        return -1.5;
                                    },
                                },
                                tag: {
                                    respond: 1,
                                    respondShan: 1,
                                    damage: 1,
                                    multitarget: 1,
                                    multineg: 1,
                                },
                            },
                        },
