                        lg_shenhaijuangu: {
                            audio: 'ext:诸神黄昏/Archive:2',
                            usable: 1,
                            trigger: {
                                player: 'recoverBegin',
                            },
                            //每回合限一次,当你回复体力时,你可以亮出牌堆顶的X张牌.若如此做,你可以使用其中一张牌,令此牌指定的目标角色各选择获得其中亮出的一张牌.此牌结算后,你可以重复此流程.若还有以此法亮出的牌,你随机废除1个装备栏(X为你的体力值)
                            _priority: 9,
                            async content(event, trigger, player) {
                                //QQQ
                                var cards = get.cards(player.hp);
                                player.showCards(cards);
                                while (cards.length) {
                                    const result = await player
                                        .chooseButton(['使用其中一张牌,令此牌指定的目标角色各选择获得其中亮出的一张牌', cards])
                                        .set('filterButton', (button) => player.hasUseTarget(button.link, true, true)) //第二个参数是距离,第三个是用牌次数
                                        .set('ai', (button) => player.getUseValue(button.link) + (lib.card[button.link.name].toself ? 40 : 0)).forResult();
                                    if (result.links?.length) {
                                        cards.remove(result.links[0]);
                                        const { result: result1 } = await player.chooseUseTarget(result.links[0], true, false);
                                        if (result1.targets && result1.targets[0]) {
                                            for (var i of result1.targets) {
                                                if (cards.length) {
                                                    const { result: result2 } = await i.chooseButton(['选择获得其中亮出的一张牌', cards]).set('ai', (button) => get.value(button.link) + (i.hasUseTarget(button.link, true, true) ? 0 : 10));
                                                    if (result2.links && result2.links[0]) {
                                                        i.gain(result2.links, 'gain2');
                                                        cards.remove(result2.links[0]);
                                                    }
                                                }
                                            }
                                        } else {
                                            if (player.countEnabledSlot()) {
                                                var list = [];
                                                for (var i = 1; i < 6; i++) {
                                                    if (trigger.player.hasEnabledSlot(i)) list.add(i);
                                                }
                                                var num = list.randomGet();
                                                player.disableEquip(num);
                                            }
                                            break;
                                        }
                                    } else {
                                        if (player.countEnabledSlot()) {
                                            var list = [];
                                            for (var i = 1; i < 6; i++) {
                                                if (player.hasEnabledSlot(i)) list.add(i);
                                            }
                                            var num = list.randomGet();
                                            player.disableEquip(num);
                                        }
                                        break;
                                    }
                                }
                            },
                        },
