                                if (player.countCards('h') == 0) event.goto(4);
                                ('step 1');
                                player.chooseCardButton('选择替换的牌', event.cards, [0, player.countCards('h')]).ai = function (button) {
                                    return get.value(button.link) - 5;
                                };
                                ('step 2');
