                        lg_monvdekaowen: {
                            audio: 'ext:诸神黄昏/Archive:2',
                            trigger: {
                                player: 'loseAfter',
                                global: 'gainAfter',
                            },
                            filter(event, player) {
                                var evt = event;
                                if (event.name == 'lose') {
                                    if (event.type != 'discard') return false;
                                    evt = event.parent;
                                }
                                if (evt[event.name == 'gain' ? 'bySelf' : 'notBySelf'] != true) return false;
                                var evtx = event.getl(player);
                                return evtx && evtx.cards2 && evtx.cards2.length;
                            },
                            prompt2(event, player) {
                                var evt = event.getl(player),
                                    origins = evt.cards2.map(function (i) {
                                        return get.name(i, evt.hs.includes(i) ? player : false);
                                    });
                                return '从牌堆获得' + get.translation(origins) + '？';
                            },
                            content() {
                                var num = 0,
                                    cards = [],
                                    evt = trigger.getl(player),
                                    origins = evt.cards2.map(function (i) {
                                        return get.name(i, evt.hs.includes(i) ? player : false);
                                    });
                                for (var i of origins) {
                                    var card = get.cardPile2(function (card) {
                                        return card.name == i && !cards.includes(card);
                                    });
                                    if (card) cards.push(card);
                                    else num++;
                                }
                                if (cards.length) player.gain(cards, 'gain2');
                                if (num > 0) player.loseHp(1);
                                player.swapHandcards(trigger.player);
                                player.addTempSkill('lg_shinue', { player: 'phaseEnd' });
                            },
                        },
