                        lg_kaixuanzhijian: {
                            audio: 'ext:诸神黄昏/Archive:2',
                            trigger: {
                                global: 'judge',
                            },
                            filter(event, player) {
                                if (event.player == player) return false;
                                return event.player.countCards('h') || player.countCards('h');
                            },
                            check(event, player) {
                                var target = event.player;
                                if (get.attitude(player, target) <= 0) {
                                    if (event.judge(target.judging) >= 0) return true;
                                } else {
                                    if (event.judge(target.judging) < 0) return true;
                                }
                                return false;
                            },
                            logTarget: 'player',
                            content() {
                                'step 0';
                                if (!trigger.player.countCards('h')) {
                                    event._result = { bool: false };
                                } else {
                                    var next = trigger.player
                                        .chooseBool(function () {
                                            return trigger.player.countCards('h', function (card) {
                                                return trigger.judge(card) > 0;
                                            });
                                        })
                                        .set('judging', trigger.player.judging[0]);
                                    next.set('prompt', '是否弃置一张手牌？');
                                }
                                ('step 1');
                                event.resultBool = result.bool;
                                if (event.resultBool) {
                                    trigger.player.chooseToDiscard(1, true, 'h');
                                    trigger.player.damage();
                                } else if (!player.countCards('h')) {
                                    event.finish();
                                    return;
                                }
                                ('step 2');
                                var tip = get.translation(trigger.player) + '的' + (trigger.judgestr || '') + '判定为' + get.translation(trigger.player.judging[0]) + ',需打出一张手牌';
                                if (event.resultBool) {
                                    tip += '代替之';
                                    event.current = trigger.player;
                                    var ai = function (card) {
                                        var trigger = _status.event.getTrigger();
                                        var player = _status.event.player;
                                        var judging = _status.event.judging;
                                        var result = trigger.judge(card) - trigger.judge(judging);
                                        var attitude = get.attitude(player, trigger.player);
                                        if (attitude == 0 || result == 0) return 0;
                                        if (attitude > 0) {
                                            return result - get.value(card) / 2;
                                        } else {
                                            return -result - get.value(card) / 2;
                                        }
                                    };
                                } else {
                                    tip += '替换之';
                                    event.current = player;
                                    var ai = function (card) {
                                        var trigger = _status.event.getTrigger();
                                        var player = _status.event.current;
                                        var judging = _status.event.judging;
                                        var result = trigger.judge(card) - trigger.judge(judging);
                                        var attitude = get.attitude(player, trigger.player);
                                        if (attitude == 0 || result == 0) return 0;
                                        if (attitude > 0) {
                                            return result;
                                        } else {
                                            return -result;
                                        }
                                    };
                                }
                                if (
                                    event.current.countCards('h', function (card) {
                                        var mod2 = game.checkMod(card, player, 'unchanged', 'cardEnabled2', player);
                                        if (mod2 != 'unchanged') return mod2;
                                        var mod = game.checkMod(card, player, 'unchanged', 'cardRespondable', player);
                                        if (mod != 'unchanged') return mod;
                                        return true;
                                    }) == 0
                                ) {
                                    event.finish();
                                } else {
                                    var next = event.current.chooseCard(
                                        tip,
                                        'h',
                                        function (card) {
                                            var player = _status.event.current;
                                            var mod2 = game.checkMod(card, player, 'unchanged', 'cardEnabled2', player);
                                            if (mod2 != 'unchanged') return mod2;
                                            var mod = game.checkMod(card, player, 'unchanged', 'cardRespondable', player);
                                            if (mod != 'unchanged') return mod;
                                            return true;
                                        },
                                        true
                                    );
                                    next.set('current', event.current);
                                    next.set('judging', trigger.player.judging[0]);
                                    next.set('ai', ai);
                                }
                                ('step 3');
                                if (result.bool && result.cards) {
                                    event.current.respond(result.cards, 'highlight', 'noOrdering');
                                } else event.finish();
                                ('step 4');
                                if (result.bool) {
                                    if (event.resultBool) {
                                        if (trigger.player.judging[0].clone) {
                                            trigger.player.judging[0].clone.classList.remove('thrownhighlight');
                                            game.broadcast(function (card) {
                                                if (card.clone) {
                                                    card.clone.classList.remove('thrownhighlight');
                                                }
                                            }, trigger.player.judging[0]);
                                            game.addVideo('deletenode', player, get.cardsInfo([trigger.player.judging[0].clone]));
                                        }
                                        game.cardsDiscard(trigger.player.judging[0]);
                                    } else {
                                        player.$gain2(trigger.player.judging[0]);
                                        player.gain(trigger.player.judging[0]);
                                    }
                                    trigger.player.judging[0] = result.cards[0];
                                    trigger.orderingCards.addArray(result.cards);
                                    game.log(trigger.player, '的判定牌改为', result.cards[0]);
                                }
                                ('step 5');
                            },
                            ai: {
                                rejudge: true,
                                skillTagFilter(player, tag, arg) {
                                    if (tag == 'rejudge') {
                                        if (player == arg) return false;
                                    }
                                },
                                tag: {
                                    rejudge: 1,
                                },
                            },
                        },
