                                        if (typeof card != 'object' || (card.name != 'sha' && card.suit != 'diamond')) return false;
                                        player._lg_degulayaolan1_judging = true;
                                        var effect = lib.skill.lg_degulayaolan1.aiJudge(card, player, target);
                                        delete player._lg_degulayaolan1_judging;
