                        lg_qiheizhishang: {
                            audio: 'ext:诸神黄昏/Archive:2',
                            usable: 1,
                            trigger: {
                                global: 'judge',
                            },
                            logTarget: 'player',
                            filter(event, player) {
                                return event.player.countCards('he') > 0 && player.countCards('hej');
                            },
                            judgeCheck(card, bool) {
                                var color = get.color(card);
                                if (color == 'black') {
                                    if (bool) return 5;
                                    return 4;
                                } else {
                                    if (bool) return 2;
                                }
                                return -1;
                            },
                            content() {
                                'step 0';
                                trigger.player
                                    .chooseCard(get.translation(trigger.player) + '的' + (trigger.judgestr || '') + '判定为' + get.translation(trigger.player.judging[0]) + ',' + get.prompt('lg_qiheizhishang'), 'he', function (card) {
                                        var player = _status.event.player;
                                        var mod2 = game.checkMod(card, player, 'unchanged', 'cardEnabled2', player);
                                        if (mod2 != 'unchanged') return mod2;
                                        var mod = game.checkMod(card, player, 'unchanged', 'cardRespondable', player);
                                        if (mod != 'unchanged') return mod;
                                        return true;
                                    })
                                    .set('ai', function (card) {
                                        var trigger = _status.event.getTrigger();
                                        var player = _status.event.player;
                                        var judging = _status.event.judging;
                                        var result = trigger.judge(card) - trigger.judge(judging);
                                        var attitude = get.attitude(player, trigger.player);
                                        if (attitude == 0 || result == 0) {
                                            if (trigger.player != player) return 0;
                                            if (
                                                game.hasPlayer(function (current) {
                                                    return get.attitude(player, current) < 0;
                                                })
                                            ) {
                                                var checkx = lib.skill.lg_qiheizhishang.judgeCheck(card, true) - lib.skill.lg_qiheizhishang.judgeCheck(judging);
                                                if (checkx > 0) return checkx;
                                            }
                                            return 0;
                                        }
                                        if (attitude > 0) {
                                            return result;
                                        } else {
                                            return -result;
                                        }
                                    })
                                    .set('judging', trigger.player.judging[0]);
                                ('step 1');
                                if (result.bool) {
                                    trigger.player.respond(result.cards, 'highlight', 'noOrdering');
                                } else {
                                    event.finish();
                                }
                                ('step 2');
                                if (result.bool) {
                                    trigger.player.$gain2(trigger.player.judging[0]);
                                    trigger.player.gain(trigger.player.judging[0]);
                                    var card = result.cards[0];
                                    if (get.color(card) == 'black') {
                                        player.turnOver();
                                    } else {
                                        if (player.countCards('he')) player.chooseToDiscard('弃置两张牌', 'he', 2, true);
                                    }
                                    trigger.player.judging[0] = result.cards[0];
                                    trigger.orderingCards.addArray(result.cards);
                                    game.log(trigger.player, '的判定牌改为', result.cards[0]);
                                }
                                ('step 3');
                            },
                            ai: {
                                rejudge: true,
                                tag: {
                                    rejudge: 1,
                                },
                            },
                        },
                        lg_posuiliehen: {
                            nobracket: true,
                            audio: 'ext:诸神黄昏/Archive:2',
                            trigger: {
                                player: ['turnOverAfter', 'damageAfter'],
                            },
                            init(player) {
                                player.storage.lg_posuiliehenUse = false;
                            },
                            intro: {
                                name: '碎',
                                content: '你的手牌上限与攻击范围+#',
                            },
                            marktext: '碎',
                            filter(event, player) {
                                return !player.storage.lg_posuiliehenUse;
                            },
                            check(event, player) {
                                if (player.countMark('lg_posuiliehen') == game.countPlayer()) return false;
                                return true;
                            },
                            popup: false,
                            content() {
                                player.popup('破碎裂痕', 'thunder');
                                player.addMark('lg_posuiliehen');
                                if (player.countMark('lg_posuiliehen') == 0) player.unmarkSkill('lg_posuiliehen');
                                if (player.getAttackRange() + player.getGlobalFrom() - 1 > game.countPlayer()) {
                                    player.storage.lg_posuiliehenUse = true;
                                }
                            },
                            mod: {
                                attackFrom(from, to, distance) {
                                    if (from.hasMark('lg_posuiliehen')) return distance - from.countMark('lg_posuiliehen');
                                },
                                maxHandcard(player, num) {
                                    return (num += player.countMark('lg_posuiliehen'));
                                },
                            },
                            ai: {
                                effect: {
                                    target(card, player, target) {
                                        if ((!player.storage.lg_posuiliehenUse && player == target && get.subtype(card) == 'equip1') || get.subtype(card) == 'equip4') {
                                            if (get.equipValue(card) <= 7.5) return 0;
                                        }
                                    },
                                },
                            },
                            group: ['lg_posuiliehen_draw'],
                            subSkill: {
                                draw: {
                                    popup: false,
                                    trigger: {
                                        player: 'phaseUseBefore',
                                    },
                                    filter(event, player) {
                                        return player.countCards('h') < player.getHandcardLimit();
                                    },
                                    prompt(event, player) {
                                        var num = player.getHandcardLimit();
                                        return '将手牌数补至' + get.cnNumber(num) + '张';
                                    },
                                    check(event, player) {
                                        var attack = player.getAttackRange() + player.getGlobalFrom();
                                        if (attack == game.countPlayer()) return true;
                                        var cards = player.countCards('h');
                                        var num = player.getHandcardLimit();
                                        if (num - cards > 1) return true;
                                        if (num - cards == 1) {
                                            if (player.hp < 3) return true;
                                            return false;
                                        }
                                        return false;
                                    },
                                    content() {
                                        player.popup('破碎裂痕', 'thunder');
                                        player.drawTo(player.getHandcardLimit());
                                        if (player.hasMark('lg_posuiliehen')) player.removeMark('lg_posuiliehen');
                                        else player.addMark('lg_posuiliehen', -1);
                                    },
                                },
                            },
                        },
