                                        for (var i = 0; i < players.length; i++) {
                                            if (players[i] != player && players[i].countCards('j')) {
                                                if (get.attitude(player, players[i]) >= 0 && get.attitude(players[i], player) >= 0) {
                                                    num++;
                                                } else {
                                                    num--;
                                                }
                                            }
                                        }
